import{_ as e,c as r,o as i,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"3、【屯】 震下坎上","description":"温公易说 - 3、【屯】 震下坎上","frontmatter":{"title":"3、【屯】 震下坎上","description":"温公易说 - 3、【屯】 震下坎上"},"headers":[],"relativePath":"zh/classics/wengong/004.md","filePath":"zh/classics/wengong/004.md"}'),n={name:"zh/classics/wengong/004.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_3、【屯】-震下坎上" tabindex="-1">3、【屯】 震下坎上 <a class="header-anchor" href="#_3、【屯】-震下坎上" aria-label="Permalink to “3、【屯】 震下坎上”">​</a></h1><h3 id="彖曰-屯刚柔始交而难生-动乎险中-大亨贞。雷雨之动-满盈天造草昧-宜建侯而不寜。" tabindex="-1">彖曰：屯刚柔始交而难生，动乎险中，大亨贞。雷雨之动，满盈天造草昧，宜建侯而不寜。 <a class="header-anchor" href="#彖曰-屯刚柔始交而难生-动乎险中-大亨贞。雷雨之动-满盈天造草昧-宜建侯而不寜。" aria-label="Permalink to “彖曰：屯刚柔始交而难生，动乎险中，大亨贞。雷雨之动，满盈天造草昧，宜建侯而不寜。”">​</a></h3><h3 id="象曰-云雷屯-君子以经纶。" tabindex="-1">象曰：云雷屯，君子以经纶。 <a class="header-anchor" href="#象曰-云雷屯-君子以经纶。" aria-label="Permalink to “象曰：云雷屯，君子以经纶。”">​</a></h3><p>屯者何？草木之始生也，贯地而出。屯然其难也，象曰君子以经纶。经纶者何？犹云纲纪也。屯者结之不解者也，结而不解则乱，乱而不缉则穷。是以君子设纲布纪，以缉其乱，解其结，然后物得其分，事得其序，治屯之道也。</p><h3 id="初九-盘桓-利居贞-利建侯。-象曰-虽盘桓-志行正也。以贵下贱-大得民也。" tabindex="-1">初九：盘桓，利居贞，利建侯。 象曰：虽盘桓，志行正也。以贵下贱，大得民也。 <a class="header-anchor" href="#初九-盘桓-利居贞-利建侯。-象曰-虽盘桓-志行正也。以贵下贱-大得民也。" aria-label="Permalink to “初九：盘桓，利居贞，利建侯。 象曰：虽盘桓，志行正也。以贵下贱，大得民也。”">​</a></h3><p>屯初九盘桓者何？治屯之道不可遽也。利居贞者何？治之不正愈以乱之也。利建侯者何？建侯所以治其纲也。治其纲百目张，夫又何乱之不缉，何结之不解乎？此之谓经纶之道也。</p><h3 id="六二-屯如邅如-乘马班如-匪-婚媾女子-贞不字-十年乃字。-象曰-六二之难-乘刚也。十年乃字-反常也。" tabindex="-1">六二：屯如邅如，乘马班如，匪？婚媾女子，贞不字，十年乃字。 象曰：六二之难，乘刚也。十年乃字，反常也。 <a class="header-anchor" href="#六二-屯如邅如-乘马班如-匪-婚媾女子-贞不字-十年乃字。-象曰-六二之难-乘刚也。十年乃字-反常也。" aria-label="Permalink to “六二：屯如邅如，乘马班如，匪？婚媾女子，贞不字，十年乃字。 象曰：六二之难，乘刚也。十年乃字，反常也。”">​</a></h3><p>人臣之道，患不正也，患不一也。茍一而正，通可必也。十年之屯，犹一日也。</p><h3 id="六三-即鹿无虞-惟入于林中-君子几不如舍-往吝。-象曰-即鹿无虞-以从禽也。君子舍之-往吝穷也。" tabindex="-1">六三：即鹿无虞，惟入于林中，君子几不如舍，往吝。 象曰：即鹿无虞，以从禽也。君子舍之，往吝穷也。 <a class="header-anchor" href="#六三-即鹿无虞-惟入于林中-君子几不如舍-往吝。-象曰-即鹿无虞-以从禽也。君子舍之-往吝穷也。" aria-label="Permalink to “六三：即鹿无虞，惟入于林中，君子几不如舍，往吝。 象曰：即鹿无虞，以从禽也。君子舍之，往吝穷也。”">​</a></h3><h3 id="六四-乘马班如-求婚媾-往吉-无不利。-象曰-求而往-明也。" tabindex="-1">六四：乘马班如，求婚媾，往吉，无不利。 象曰：求而往，明也。 <a class="header-anchor" href="#六四-乘马班如-求婚媾-往吉-无不利。-象曰-求而往-明也。" aria-label="Permalink to “六四：乘马班如，求婚媾，往吉，无不利。 象曰：求而往，明也。”">​</a></h3><h3 id="九五-屯其膏-小贞吉-大贞凶。-象曰-屯其膏-施未光也。" tabindex="-1">九五：屯其膏，小贞吉，大贞凶。 象曰：屯其膏，施未光也。 <a class="header-anchor" href="#九五-屯其膏-小贞吉-大贞凶。-象曰-屯其膏-施未光也。" aria-label="Permalink to “九五：屯其膏，小贞吉，大贞凶。 象曰：屯其膏，施未光也。”">​</a></h3><h3 id="上六-乘马班如-泣血涟如。-象曰-泣血涟如-如何可长也。" tabindex="-1">上六：乘马班如，泣血涟如。 象曰：泣血涟如，如何可长也。 <a class="header-anchor" href="#上六-乘马班如-泣血涟如。-象曰-泣血涟如-如何可长也。" aria-label="Permalink to “上六：乘马班如，泣血涟如。 象曰：泣血涟如，如何可长也。”">​</a></h3>',12)])])}const f=e(n,[["render",l]]);export{b as __pageData,f as default};
